  'trig.hint': { en: 'LT/RT input window. Begin/end trim the pull; the switch gates the whole block (off = factory 5–100%). Still one-to-one: no macros, no turbo.', zh: 'LT/RT 输入窗口。起点/终点裁剪行程；开关控制整个模块（关闭=出厂 5–100%）。仍是一对一：无宏、无连发。', ja: 'LT/RT入力ウィンドウ。開始/終了で行程を調整。有効化で全体を適用（オフ=工場出荷5–100%）。1対1のまま：マクロ・連射なし。', ru: 'Окно ввода LT/RT. Начало/конец подрезают ход; выключатель управляет всем блоком (выкл. = заводские 5–100%). Всё равно один к одному: без макросов и турбо.' },
  'trig.enable': { en: 'Deadzone enabled', zh: '启用死区', ja: 'デッドゾーン有効', ru: 'Мёртвая зона вкл.' },
  'lab.linTitle': { en: 'Linearity bench', zh: '线性测试台', ja: 'リニアリティベンチ', ru: 'Стенд линейности' },
  'lab.linHint': { en: 'Guided center-to-edge passes on the live stream. Hold still to set center, then push to the rim at a steady 2–3 s pace — at least 3 passes. Scores tremor (jitter share), linearity (ideal tracking) and resolution (mean step). Rim-hold ends each pass; passes normalize by their own max.', zh: '基于实时流的分步中心→边缘测试。静止握持定中心，然后2–3秒匀速推向边缘——至少3次。评分含抖动占比、线性度和分辨率。到达边缘保持即结束单次，并以自身最大值归一化。', ja: 'ライブ入力でのガイド付き中央→外周テスト。静止でセンター設定後、2〜3秒で一定に外周へ — 最低3パス。ジッター率・リニアリティ・分解能を採点。外周保持で確定、最大値で正規化。', ru: 'Ведомые проходы центр→край по живому вводу. Замрите для центра, затем ровно 2–3 с ведите к краю — минимум 3 прохода. Считаем дрожание, линейность и разрешение. Конец прохода — удержание края, нормировка на свой максимум.' },
  'lab.linStart': { en: 'Start', zh: '开始', ja: '開始', ru: 'Начать' },
  'lab.linIdle': { en: 'Idle — pick a stick, then start.', zh: '空闲——选择摇杆后开始。', ja: '待機中 — スティックを選んで開始。', ru: 'Жду — выберите стик и начните.' },
  'lab.linCentering': { en: 'Hold the stick perfectly still…', zh: '保持摇杆完全静止…', ja: 'スティックを完全に静止させてください…', ru: 'Держите стик совершенно неподвижно…' },
  'lab.linPush': { en: 'Push center → rim, steady 2–3 s…', zh: '匀速将摇杆推向边缘，2–3 秒…', ja: '中央→外周へ2〜3秒で一定に倒す…', ru: 'Ведите от центра к краю ровно 2–3 с…' },
  'lab.linReturn': { en: 'Back to center, then push again…', zh: '回到中心，再推一次…', ja: '中央に戻して、もう一度…', ru: 'Верните в центр и толкните снова…' },
