  'lab.linRes': { en: 'Resolution', zh: '分辨率', ja: '分解能', ru: 'Разрешение' },
  'lab.linAvg': { en: 'Average', zh: '平均', ja: '平均', ru: 'Среднее' },
  'lab.dpTitle': { en: 'Kernel poll check', zh: '内核回报率检测', ja: 'カーネルポーリング測定', ru: 'Проверка опроса ядра' },
  'lab.dpHint': { en: 'True USB poll rate via an elevated kernel trace (logman + tracerpt, ~8 s). Windows asks for admin once per run; wiggle the sticks while it captures. Kernel method follows DeepPoll (Marius Heier, MIT).', zh: '通过提权内核跟踪测真实 USB 回报率（约 8 秒）。每次运行 Windows 会请求一次管理员权限，采集时请晃动摇杆。方法沿用 DeepPoll（Marius Heier，MIT）。', ja: '管理者権限のカーネルトレースで真のUSBポーリングを測定（約8秒）。実行ごとに管理者承認が必要、取得中はスティックを動かしてください。方式はDeepPoll（Marius Heier、MIT）に準拠。', ru: 'Истинная частота USB через трассировку ядра (около 8 с). Windows спросит права администратора, во время захвата двигайте стики. Метод — по DeepPoll (Marius Heier, MIT).' },
  'lab.dpRun': { en: 'Run kernel check', zh: '运行内核检测', ja: 'カーネル測定を実行', ru: 'Запустить проверку' },
  'lab.dpAdmin': { en: 'Needs Windows admin — UAC asks once.', zh: '需要 Windows 管理员权限——UAC 会询问一次。', ja: 'Windows管理者権限が必要 — UACが一度確認します。', ru: 'Нужны права администратора — UAC спросит один раз.' },
  'lab.dpRunning': { en: 'Tracing USB — wiggle the sticks…', zh: '正在跟踪 USB——请晃动摇杆…', ja: 'USBトレース中 — スティックを動かしてください…', ru: 'Трассировка USB — двигайте стики…' },
  'lab.dpDenied': { en: 'Admin was declined — no trace ran.', zh: '已拒绝管理员权限——未进行跟踪。', ja: '管理者が拒否されました — 測定していません。', ru: 'Права отклонены — захват не выполнялся.' },
  'lab.dpFailed': { en: 'Kernel trace failed.', zh: '内核跟踪失败。', ja: 'カーネルトレース失敗。', ru: 'Трассировка ядра не удалась.' },
