  'cal.bench': { en: 'Calibration bench', zh: '校准台', ja: 'キャリブレーションベンチ', ru: 'Стенд калибровки' },
  'cal.fineHint': { en: "Before starting, release both sticks to center. Once the controller reports calibration active, slowly rotate each stick through its full range around the edge. Save unlocks only after the controller reports both sticks complete.", zh: "开始前松开摇杆使其回到中心。手柄报告校准已启动后，缓慢转动每个摇杆，沿外圈覆盖完整行程。手柄报告两个摇杆都完成后才可保存。", ja: "開始前に両方のスティックを中央に戻します。コントローラーが調整開始を報告したら、各スティックを外周に沿ってゆっくり全範囲回します。両方の完了が報告されるまで保存できません。", ru: "Перед началом отпустите стики и верните их в центр. После сообщения о начале калибровки медленно проведите каждый стик по внешнему краю. Сохранение станет доступно, когда контроллер отметит оба стика." },
  'cal.fineStep': { en: 'Step {n} of 5', zh: '第 {n} 步，共 5 步', ja: '全5ステップ中 {n} 番目', ru: 'Шаг {n} из 5' },
  'cal.connected': { en: 'Controller connected', zh: '控制器已连接', ja: 'コントローラー接続済み', ru: 'Геймпад подключён' },
  'cal.fineSetupTitle': { en: 'Ready when you are', zh: '准备就绪', ja: '準備ができました', ru: 'Готово к началу' },
  'cal.fineSetupBody': { en: "Set the controller on a steady surface. Leave both sticks centered, then start hardware calibration.", zh: "将手柄放在稳固平面上，让两个摇杆保持居中，然后开始硬件校准。", ja: "コントローラーを安定した場所に置き、両方のスティックを中央にしてからハードウェア調整を開始します。", ru: "Положите геймпад на устойчивую поверхность. Оставьте стики по центру и запустите аппаратную калибровку." },
  'cal.fineProgress': { en: "HARDWARE CALIBRATION", zh: "硬件校准", ja: "ハードウェア校正", ru: "АППАРАТНАЯ КАЛИБРОВКА" },
