  'cal.fineFirmwareStatus': { en: "Controller report active / part mask", zh: "手柄报告 活动状态 / 部件掩码", ja: "コントローラー報告: 有効状態 / 部品マスク", ru: "Отчёт контроллера: активность / маска частей" },
  'cal.fineMovePrompt': { en: "Slowly circle each stick around its full edge. A stick is recorded after the live input covers the full range and all four corners; the controller's part mask alone is not enough.", zh: "缓慢沿外圈转动每个摇杆。实时输入覆盖完整行程和四个角后才会记录；仅有手柄部件掩码还不够。", ja: "各スティックを外周に沿ってゆっくり一周させます。ライブ入力が全範囲と四隅を通過すると記録されます。本体の部品マスクだけでは不十分です。", ru: "Медленно проведите каждый стик по полной окружности. Стик засчитывается после охвата полного диапазона и всех четырёх углов; одной маски контроллера недостаточно." },
  'cal.fineCompleteTitle': { en: 'Calibration captured', zh: '校准数据已采集', ja: '調整データを取得しました', ru: 'Калибровка собрана' },
  'cal.fineCompleteBody': { en: "The controller reports both sticks complete. Save to commit this calibration to the controller.", zh: "手柄报告两个摇杆都已完成。保存后会将校准数据写入手柄。", ja: "コントローラーが両方のスティック完了を報告しました。保存すると校正が本体に反映されます。", ru: "Контроллер сообщил о готовности обоих стиков. Сохраните, чтобы записать калибровку." },
  'cal.fineSavedTitle': { en: 'Calibration saved', zh: '校准已保存', ja: '調整を保存しました', ru: 'Калибровка сохранена' },
  'cal.fineSavedBody': { en: "The save command was sent. Calibration is stored on the controller, separate from profile settings.", zh: "已发送保存命令。校准数据储存在手柄中，与配置文件设置分开。", ja: "保存コマンドを送信しました。校正データはプロファイル設定とは別に本体へ保存されます。", ru: "Команда сохранения отправлена. Калибровка хранится в устройстве отдельно от профиля." },
