  'cal.fineFooterSetup': { en: "Standard hardware routine · both sticks · save unlocks after controller confirmation", zh: "标准硬件流程 · 双摇杆 · 手柄确认后解锁保存", ja: "標準ハードウェア調整 · 両スティック · 本体確認後に保存可能", ru: "Стандартная аппаратная калибровка · оба стика · сохранение после подтверждения" },
  'cal.fineFooterActive': { en: "Rotate both sticks slowly until both completion badges turn green.", zh: "缓慢转动两个摇杆，直到两个完成状态都变为绿色。", ja: "両方の完了バッジが緑になるまで、両方のスティックをゆっくり回します。", ru: "Медленно вращайте оба стика, пока обе отметки готовности не станут зелёными." },
