  'cal.fineDown': { en: 'Push both sticks fully down', zh: '两个摇杆推至最下方', ja: '両方のスティックを下端まで倒す', ru: 'Оба стика до упора вниз' },
  'cal.fineLeft': { en: 'Push both sticks fully left', zh: '两个摇杆推至最左方', ja: '両方のスティックを左端まで倒す', ru: 'Оба стика до упора влево' },
  'cal.fineRight': { en: 'Push both sticks fully right', zh: '两个摇杆推至最右方', ja: '両方のスティックを右端まで倒す', ru: 'Оба стика до упора вправо' },
  'cal.fineCircle': { en: 'Rotate both sticks around the edge', zh: '两个摇杆沿边缘画圈', ja: '両方のスティックを外周に沿って回す', ru: 'Оба стика по кругу вдоль края' },
  'cal.fineReadyCommit': { en: 'All steps recorded — ready to save', zh: '所有步骤已记录——可以保存', ja: '全手順を記録しました — 保存できます', ru: 'Все этапы записаны — можно сохранить' },
