  'cal.fineCancelled': { en: "Cancel command sent; no new calibration was saved.", zh: "已发送取消命令；未保存新校准。", ja: "キャンセルコマンドを送信しました。新しい校正は保存されていません。", ru: "Команда отмены отправлена; новая калибровка не сохранена." },
  'cal.stickOnly': { en: 'This routine calibrates the sticks only. Triggers are left untouched.', zh: '此流程仅校准摇杆，不会改动扳机。', ja: 'この手順ではスティックのみを調整し、トリガーは変更しません。', ru: 'Этот процесс калибрует только стики. Триггеры не затрагиваются.' },
  'cal.ljTitle': { en: 'LeadJoy center check', zh: 'LeadJoy 中心检测', ja: 'LeadJoy センター確認', ru: 'Проверка центра LeadJoy' },
  'cal.ljHint': { en: 'Set the controller flat, leave both sticks untouched, then measure their resting center.', zh: '将手柄平放，松开两个摇杆，然后测量静止中心。', ja: 'コントローラーを平らに置き、両方のスティックから手を離して静止位置を測定します。', ru: 'Положите геймпад ровно, отпустите стики и измерьте положение покоя.' },
  'cal.ljReadOnly': { en: 'Read-only check: Stick Labs does not send a calibration command to the Saber Plus yet. Use the LeadJoy app for hardware recalibration.', zh: '只读检测：Stick Labs 尚未向 Saber Plus 发送校准命令。硬件校准请使用 LeadJoy 应用。', ja: '読み取り専用です。Stick Labs は Saber Plus に校正コマンドをまだ送信しません。ハードウェア校正には LeadJoy アプリを使用してください。', ru: 'Проверка только для чтения: Stick Labs пока не отправляет Saber Plus команду калибровки. Для аппаратной калибровки используйте приложение LeadJoy.' },
