  'sticks.dzHint': { en: 'Start/End bound the input; anti-deadzone is the output floor/ceiling (snap for FPS).', zh: '起点/终点限定输入；反死区是输出上下限（FPS 跟手）。', ja: '開始/終了で入力範囲、アンチは出力上下限（FPS向け）。', ru: 'Начало/конец ограничивают вход; антизона — пол/потолок выхода (снап для FPS).' },
  'sticks.outerNote1': { en: 'A positive buffer pulls max output earlier (hotter rim); neutral removes the boundary entirely.', zh: '正缓冲提前达到最大输出（更热的边缘）；中性则完全移除边界。', ja: '正バッファで最大出力が早まり、中性で境界解除。', ru: 'Положительный буфер раньше даёт полный выход (горячий край); нейтраль полностью снимает границу.' },
  'sticks.curveHint': { en: 'Input runs left to right; output runs bottom to top. Drag a point to shape the response.', zh: '输入从左到右，输出从下到上。拖动曲线点来调整响应。', ja: '入力は左から右、出力は下から上です。点をドラッグして応答を調整できます。', ru: 'Вход идёт слева направо, выход — снизу вверх. Перетаскивайте точки, чтобы менять отклик.' },
  'sticks.curveClickHint': { en: 'Drag a point to move it, or click the chart to add a point. Dashed amber shows the curve sent to the controller.', zh: '拖动点来移动，或点击图表添加新点。橙色虚线显示写入手柄的曲线。', ja: '点をドラッグして移動、グラフをクリックして点を追加できます。オレンジの破線はコントローラーへ送る曲線です。', ru: 'Перетащите точку, чтобы переместить её, или нажмите на график, чтобы добавить точку. Янтарный пунктир показывает кривую для контроллера.' },
