  'sticks.fixed9': { en: 'Fixed 9 points per stick — no add/remove. X positions are hardware slots.', zh: '每摇杆固定 9 点——不可增删。X 为硬件槽位。', ja: '1本9点固定 — 増減不可。Xはハード枠。', ru: 'Фиксированно 9 точек на стик — без добавления/удаления. X — аппаратные слоты.' },
  'sticks.shapeNote': { en: 'No shape/gate flags on this pad: output always follows the curve.', zh: '此手柄无形状/档位标志：输出始终跟随曲线。', ja: 'このパッドに形状フラグなし：出力は常にカーブ通り。', ru: 'У этого геймпада нет флагов формы: выход всегда следует кривой.' },
  'apex.resetHint': { en: 'Returns both curves to the Slow baseline. Then Send to apply.', zh: '将双曲线恢复到 Slow 基线，然后发送以应用。', ja: '両カーブをSlow基準に戻します。送信して適用。', ru: 'Возвращает обе кривые к базе Slow. Затем отправьте для применения.' },
