  'device.pollHint': { en: 'Report-rate gear. Hz labels are the vendor claim.', zh: '回报率档位。Hz 为厂商标称。', ja: 'レポートレート。Hzは公称値。', ru: 'Ступень частоты опроса. Метки Гц — заявление производителя.' },
  'device.bitHint': { en: 'Hardware tops at 12-bit. Games see 256 steps regardless.', zh: '硬件最高 12 位。游戏始终只看到 256 级。', ja: '最大12bit。ゲーム側は常に256段階。', ru: 'Железо — максимум 12 бит. Игры всё равно видят 256 шагов.' },
  'device.bitNote': { en: '12-bit is the most the sensor resolves; games receive 256 steps regardless.', zh: '传感器最高分辨 12 位；游戏始终收到 256 级。', ja: 'センサー最大12bit、ゲーム側は常に256段階。', ru: 'Сенсор различает максимум 12 бит; игры получают 256 шагов в любом случае.' },
